#!/usr/bin/env python3
"""Ross's transcript filer: append any Friend-Message beats not yet on main."""
import json, re, glob, subprocess, sys, os

REPO = '/tmp/rosswork'
os.chdir(REPO)

branches = {'rachel': 'Rachel', 'monica': 'Monica', 'phoebe': 'Phoebe',
            'joey': 'Joey', 'chandler': 'Chandler', 'ross': 'Ross'}
b2s = {v: k for k, v in branches.items()}

def sh(args):
    return subprocess.run(['git'] + args, capture_output=True, text=True, check=True).stdout

shas = sorted(set(sh(['log', '--format=%H', 'origin/friend/' + b]).split()))
beats = []
for sha in shas:
    body = sh(['show', '-s', '--format=%H%x00%ct%x00%cI%x00%B', sha])
    if 'Friend-Message: 1' not in body:
        continue
    h, ct, ci, msg = body.split('\x00', 3)
    ep = re.search(r'^Episode:\s*(\S+)\s*$', msg, re.M)
    spk = re.search(r'^Speaker:\s*(.+?)\s*$', msg, re.M)
    if not ep or not spk:
        continue  # a note, not an utterance
    if not re.search(r'^Friend-Message: 1\s*$', msg, re.M):
        continue
    beats.append(dict(sha=h, ct=int(ct), ci=ci, ep=ep.group(1), spk=spk.group(1), msg=msg))
beats.sort(key=lambda d: (d['ct'], d['sha']))

known = set()
for f in glob.glob('S*/E*.md'):
    known |= set(re.findall(r'Source: friend/\w+ @ ([0-9a-f]{40})', open(f).read()))

def utterance(msg):
    lines = msg.split('\n')
    i = [n for n, l in enumerate(lines) if l.startswith('Reply-To:')][0]
    return '\n'.join(lines[i + 1:]).strip('\n')

by_ep = {}
for b in beats:
    if b['sha'] in known:
        continue
    by_ep.setdefault(b['ep'], []).append(b)

changed = []
for ep, items in sorted(by_ep.items()):
    path = ep + '.md'
    if not os.path.exists(path):
        print('MISSING FILE', path)
        continue
    text = open(path).read()
    chunks = []
    for b in items:
        chunks.append(f"**{b['spk']}** ({b['ci']})\n\nSource: friend/{b2s[b['spk']]} @ {b['sha']}\n\n{utterance(b['msg'])}\n")
    body = text.rstrip('\n') + '\n\n' + '\n'.join(chunks)
    open(path, 'w').write(body)
    changed.append((path, len(items)))
    print('appended', len(items), 'to', path)

if changed:
    sh(['add'] + [p for p, _ in changed])
    msg = 'Ross: file ' + ', '.join(f'{n} beats of {p.replace(".md","")}' for p, n in changed)
    sh(['commit', '-m', msg])
    print('committed:', msg)
    sh(['push', 'origin', 'HEAD:refs/heads/main'])
    print('pushed')
else:
    print('nothing missing')
